/* SPS samples generated by Linux ffmpeg/libx264 from our own test patterns. */
#include "SFSPS.h"
#include <assert.h>
#include <stdio.h>
static const uint8_t progressive[]={0x67,0x42,0xc0,0x1e,0xda,0x2,0x80,0xbf,0xe5,0xc0,0x44,0x0,0x0,0x3,0x0,0x4,0x0,0x0,0x3,0x0,0xf0,0x3c,0x58,0xba,0x80};
static const uint8_t interlaced[]={0x67,0x64,0x0,0x15,0xac,0xd9,0x42,0x8,0xd8,0x8,0x80,0x0,0x0,0x3,0x0,0x80,0x0,0x0,0x19,0xf,0x8a,0x14,0xcb};
int main(void){
 assert(sf_vt_h264_progressive(progressive,sizeof(progressive)));
 assert(!sf_vt_h264_progressive(interlaced,sizeof(interlaced)));
 for(size_t n=0;n<5;n++)assert(!sf_vt_h264_progressive(progressive,n));
 assert(!sf_vt_h264_progressive(NULL,20));
 uint8_t fuzz[128];uint32_t seed=0x814635ac;
 for(unsigned n=0;n<50000;n++){
  for(unsigned i=0;i<128;i++){seed=seed*1664525u+1013904223u;fuzz[i]=seed>>24;}
  (void)sf_vt_h264_progressive(fuzz,n%129);
 }
 puts("SPS progressive/interlaced/short/null/50000 bounded fuzz checks PASS (host only)");
 return 0;
}
